def dump(path, value):
    path.write_text(json.dumps(value, indent=2), encoding='utf8')


def plan_nodes(expected, shards):
    """Use observed costs as scheduling hints, never as test selection evidence.

    Light modules stay together to avoid importing every test module in every
    Python. Modules larger than a balanced bin are split at original nodeids.
    """
    weights = {node: max(PROFILE_NODE_SECONDS.get(node, .1), .01) for node in expected}
    modules = {}
    for node in expected:
        modules.setdefault(node.split('::', 1)[0], []).append(node)
    target = sum(weights.values()) / shards
    jobs = []
    for nodes in modules.values():
        if sum(weights[node] for node in nodes) > .55 * target:
            jobs.extend([[node] for node in nodes])
        else:
            jobs.append(nodes)
    jobs.sort(key=lambda nodes: sum(weights[node] for node in nodes), reverse=True)
    plans = [[] for _ in range(shards)]
    loads = [0.] * shards
    for nodes in jobs:
        index = min(range(shards), key=lambda value: (loads[value], value))
        plans[index].extend(nodes)
        loads[index] += sum(weights[node] for node in nodes)
    flattened = [node for plan in plans for node in plan]
    if not all(plans) or len(flattened) != len(expected) or set(flattened) != set(expected):
        raise RuntimeError('scheduler lost or duplicated original nodeids')
    return plans, {'strategy': 'module_affinity_lpt', 'hint_source': PROFILE_SOURCE,
                   'estimated_seconds': loads,
                   'modules_per_shard': [len({node.split('::', 1)[0] for node in plan}) for plan in plans]}


def main():
    if sys.flags.optimize:
        raise RuntimeError('optimized Python cannot run acceptance')
    out = Path(sys.argv[1]).resolve()
    stop_memory = threading.Event()
    def sample_memory():
        with (out / 'group_memory.jsonl').open('a', encoding='utf8', buffering=1) as stream:
            while not stop_memory.is_set():
                stream.write(json.dumps(memory_snapshot()) + '\n')
                stop_memory.wait(1.)
    memory_thread = threading.Thread(target=sample_memory, daemon=True)
    memory_thread.start()
    evidence = Evidence(out)
    status = pytest.main(['--collect-only', '-q', '-p', 'no:cacheprovider', '-p', 'hypothesis.extra.pytestplugin',
                          '-c', str(Path(__file__).with_name('daily_pytest.ini')),
                          '--rootdir', str(Path.cwd()), '--confcutdir', str(Path.cwd()),
                          '-o', 'addopts=', *sys.argv[2:]], plugins=[evidence])
    expected = evidence.selected
    dump(out / 'expected_collection.json', {'collected': evidence.collected, 'selected': expected, 'deselected': evidence.deselected})
    if status or not expected or expected != evidence.collected or evidence.deselected or len(set(expected)) != len(expected):
        raise RuntimeError('full core30 collection rejected')
    shards = min(6, os.cpu_count() or 1, len(expected))
    plans, planning = plan_nodes(expected, shards)
    dump(out / 'plan_summary.json', planning)

    def child(index):
        directory = out / ('shard' + str(index)); directory.mkdir()
        temp = out / ('temp' + str(index)); temp.mkdir()
        plan = directory / 'plan.json'; dump(plan, plans[index])
        env = {**os.environ, 'TEMP': str(temp), 'TMP': str(temp), 'HYPOTHESIS_STORAGE_DIRECTORY': str(temp / 'hypothesis')}
        command = [sys.executable, '-B', '-X', 'utf8', str(Path(__file__).with_name('daily_microcap_test_worker.py')), str(directory), '--plan', str(plan)]
        with (directory / 'process.log').open('w', encoding='utf8') as stream:
            began = time.monotonic()
            p = subprocess.Popen(command, env=env, stdout=stream, stderr=subprocess.STDOUT)
            code = p.wait()
        dump(directory / 'process_metrics.json', {'pid': p.pid, 'elapsed_seconds': time.monotonic() - began,
                                                 'exit_code': code})
        proof = json.loads((directory / 'collection.json').read_text(encoding='utf8'))
        if proof['collected'] != plans[index] or proof['selected'] != plans[index] or proof['deselected'] or proof['executed'] != plans[index]:
            raise RuntimeError('shard collection/execution differs from plan')
        return code, proof, directory

    with ThreadPoolExecutor(max_workers=shards) as pool:
        results = list(pool.map(child, range(shards)))
    executed = [node for _, proof, _ in results for node in proof['executed']]
    if len(executed) != len(expected) or set(executed) != set(expected):
        raise RuntimeError('missing or duplicate core30 nodeids')
    merged = ET.Element('testsuites')
    for _, _, directory in results:
        root = ET.parse(directory / 'regression.xml').getroot()
        for suite in root.findall('.//testsuite'):
            merged.append(suite)
    ET.ElementTree(merged).write(out / 'regression.xml', encoding='utf8', xml_declaration=True)
    # Canonical order for comparison; raw actual order remains in each child proof.
    dump(out / 'collection.json', {'collected': expected, 'selected': expected, 'deselected': [],
                                  'executed': [node for node in expected if node in set(executed)],
                                  'executed_by_shard': [proof['executed'] for _, proof, _ in results]})
    dump(out / 'group.json', {'tests': len(expected), 'shards': shards, 'exit_codes': [code for code, _, _ in results],
                             'all_expected_nodeids_executed_once': True, 'planning': planning})
    stop_memory.set(); memory_thread.join(timeout=2)
    return 0 if all(code == 0 for code, _, _ in results) else 1


if __name__ == '__main__':
    try:
        raise SystemExit(main())
    except Exception as exc:
        directory = Path(sys.argv[1]).resolve()
        dump(directory / 'group_failure.json', {'error': str(exc)})
        raise
